      <button data-testid="inc-btn" onClick={() => setCount((c) => c + 1)}>
        Increment
      </button>
      <button data-testid="reset-btn" onClick={() => setCount(0)}>
        Reset
      </button>
    </div>
  );
}

export default SharedCounter;

